function makeMockResponse(bodyObjOrStr, contentType = "application/json") {
  const str = typeof bodyObjOrStr === "string" ? bodyObjOrStr : JSON.stringify(bodyObjOrStr);
  return {
    ok: true,
    status: 200,
    statusText: "OK",
    headers: { get: (h) => h.toLowerCase() === "content-type" ? contentType : null },
    text: async () => str,
    json: async () => typeof bodyObjOrStr === "string" ? JSON.parse(bodyObjOrStr) : bodyObjOrStr,
    blob: async () => new Blob([str], { type: contentType }),
    arrayBuffer: async () => new TextEncoder().encode(str).buffer,
    clone: function() { return this; }
  };
}

window.resolveModuCutInlineAsset = async function(urlStr) {
  if (!urlStr) return null;
  if (urlStr.endsWith("/emoji-17-0.json") || urlStr.includes("emoji-17-0.json")) {
    return makeMockResponse(window.__MODUCUT_EMOJI_INDEX__, "application/json");
  }
  if (urlStr.endsWith("/fonts/fonts.json") || urlStr.includes("fonts/fonts.json")) {
    return makeMockResponse(window.__MODUCUT_FONTS_CATALOG__, "application/json");
  }
  for (const [k, v] of Object.entries(window.__MODUCUT_INLINE_SVGS__)) {
    if (urlStr.endsWith(k) || urlStr.endsWith(k + ".svg")) {
      return makeMockResponse(v, "image/svg+xml");
    }
  }
  for (const [k, v] of Object.entries(window.__MODUCUT_INLINE_FONTS_SVG__)) {
    if (urlStr.endsWith(k)) {
      return makeMockResponse(v, "image/svg+xml");
    }
  }
  return null;
};

window.fallbackModuCutAsset = async function(urlStr) {
  if (!urlStr) return null;
  if (urlStr.includes("/symbols/") || urlStr.includes("/noto-emoji-600/")) {
    const starSvg = window.__MODUCUT_INLINE_SVGS__["/symbols/moducut-star.svg"] || '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><circle cx="50" cy="50" r="40" fill="#000"/></svg>';
    return makeMockResponse(starSvg, "image/svg+xml");
  }
  if (urlStr.endsWith(".svg")) {
    const fallbackFontSvg = window.__MODUCUT_INLINE_FONTS_SVG__["/fonts/EMS/EMSReadability.svg"];
    if (fallbackFontSvg) return makeMockResponse(fallbackFontSvg, "image/svg+xml");
  }
  return null;
};

window.handleModuCutStandaloneApi = async function(endpoint, payload) {
  if (endpoint === "loggedInUser") {
    return {
      success: true,
      userId: 130026,
      username: "iqbalnawaz072",
      email: "iqbalnawaz072@gmail.com",
      displayName: "M. Iqbal",
      avatar: "",
      userStorage: { hasOpenedCreationPanel: true },
      isAdmin: true,
      canLicenseMinisite: false,
      canLicensePro: false,
      subscription: {
        plan: "Pro",
        projectsRemaining: 9999,
        hasEverHadTrial: false,
        hasEverBeenInvoiced: false
      },
      minisiteMemberships: []
    };
  }
  if (endpoint === "getProjectCardsByProjectIds") {
    const ids = (payload && Array.isArray(payload.projectIds)) ? payload.projectIds : [];
    const allTpls = window.__MODUCUT_TEMPLATES_INDEX__ || [];
    const projectCards = ids.map(pid => {
      const found = allTpls.find(t => t.id === pid);
      return {
        projectId: pid,
        name: (found && found.name) || pid,
        previewImage: (found && found.image) || null,
        coverPhoto: null,
        ownerUsername: "moducut",
        ownerDisplayName: "ModuCut Official",
        ownerAvatar: null
      };
    });
    return { success: true, projectCards };
  }
  if (endpoint === "getSnapshots") {
    return { success: true, snapshots: [] };
  }
  if (endpoint === "getTags") {
    return {
      success: true,
      tags: [
        { tagId: 1, tagName: "Laser Cutting", slug: "laser-cutting" },
        { tagId: 2, tagName: "Boxes & Packaging", slug: "boxes" },
        { tagId: 3, tagName: "Ornaments & Gifts", slug: "ornaments" },
        { tagId: 4, tagName: "Signage & Typography", slug: "signage" }
      ]
    };
  }
  return { success: true };
};

window.loadStandaloneProjectById = async function(projectId) {
  if (!projectId) return null;
  const slug = String(projectId).toLowerCase().trim();
  if (typeof localforage !== "undefined") {
    try {
      const direct = await localforage.getItem("moducut_project_" + slug) || await localforage.getItem("moducut_template_snap_" + projectId);
      if (direct) return direct;
    } catch (_) {}
  }
  const allTpls = window.__MODUCUT_TEMPLATES_INDEX__ || [];
  const matched = allTpls.find(t => t.id === projectId || t.slug === slug || (t.name && t.name.toLowerCase().replace(/[^a-z0-9]+/g, "-") === slug));
  if (matched && window.buildStandaloneTemplateSnapshot) {
    return window.buildStandaloneTemplateSnapshot(matched);
  }
  return null;
};

